{"path":"/Remote Desktop Commander/link_6ac5be5cd98881918f28af8bca260fb8/write_file","args":{"deviceId":"8e436233-df9a-46a5-a6cc-38b3b5043a11","path":"/Users/rbhanson/.omp/agent/cactus-reflex/core.ts","mode":"rewrite","content":"export type ToolSummary = {
  name: string;
  source: string;
  description?: string;
};

export type RouteDecision = {
  names: string[];
  confidence: number;
};

export const DEFAULT_ROUTE_CONFIDENCE = 0.25;

const GENERIC_ROUTE_TOKENS = new Set([
  "tool", "tools", "search", "find", "fetch", "get", "list", "read",
  "write", "create", "update", "delete", "query", "data", "call",
  "run", "execute", "lookup", "look", "show", "use", "using",
]);

function tokens(value: string): Set<string> {
  return new Set(
    value
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter(token => token.length >= 3 && !GENERIC_ROUTE_TOKENS.has(token)),
  );
}

function routeIsGrounded(
  tools: readonly ToolSummary[],
  selectedNames: ReadonlySet<string>,
  prompt: string,
): boolean {
  if (!prompt.trim()) return false;
  const promptTokens = tokens(prompt);
  if (promptTokens.size === 0) return false;

  for (const tool of tools) {
    if (!selectedNames.has(tool.name)) continue;
    const toolTokens = tokens(`${tool.name} ${tool.description ?? ""}`);
    for (const token of toolTokens) {
      if (promptTokens.has(token)) return true;
    }
  }
  return false;
}

export function selectActiveToolNames(
  tools: readonly ToolSummary[],
  route: RouteDecision | null,
  prompt = "",
  threshold = DEFAULT_ROUTE_CONFIDENCE,
): string[] {
  const allNames = tools.map(tool => tool.name);
  if (!route || route.confidence < threshold || route.names.length === 0) {
    return allNames;
  }

  const validNames = new Set(allNames);
  const selected = new Set(route.names.filter(name => validNames.has(name)));

  if (selected.size === 0 || !routeIsGrounded(tools, selected, prompt)) {
    return allNames;
  }

  return tools
    .filter(tool => tool.source !== "mcp" || selected.has(tool.name))
    .map(tool => tool.name);
}
