{"path":"/Remote Desktop Commander/link_6ac5be5cd98881918f28af8bca260fb8/write_file","args":{"deviceId":"8e436233-df9a-46a5-a6cc-38b3b5043a11","path":"/Users/rbhanson/.omp/agent/extensions/cactus-reflex.ts","content":"import type { ExtensionAPI } from "@oh-my-pi/pi-coding-agent";
import { selectActiveToolNames, type RouteDecision, type ToolSummary } from "../cactus-reflex/core";

const ROUTER_URL = process.env.CACTUS_REFLEX_URL ?? "http://127.0.0.1:8765/route";
const ROUTER_TIMEOUT_MS = 1400;

type RouterReply = {
  ok?: boolean;
  names?: unknown;
  confidence?: unknown;
};

function summarizeTools(pi: ExtensionAPI) {
  return pi.getAllTools().map(tool => ({
    name: tool.name,
    source: tool.sourceInfo.source,
    description: tool.description ?? "",
    parameters: tool.parameters,
  }));
}

function toDecision(reply: RouterReply): RouteDecision | null {
  if (reply.ok !== true || !Array.isArray(reply.names)) return null;
  const names = reply.names.filter((name): name is string => typeof name === "string");
  const confidence = Number(reply.confidence);
  if (!Number.isFinite(confidence)) return null;
  return { names, confidence };
}

async function routePrompt(prompt: string, tools: ReturnType<typeof summarizeTools>): Promise<RouteDecision | null> {
  const external = tools.filter(tool => tool.source === "mcp");
  if (external.length === 0) return null;

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), ROUTER_TIMEOUT_MS);
  try {
    const response = await fetch(ROUTER_URL, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        prompt: prompt.slice(0, 6000),
        tools: external.map(tool => ({
          name: tool.name,
          description: tool.description,
          parameters: tool.parameters,
        })),
      }),
      signal: controller.signal,
    });
    if (!response.ok) return null;
    return toDecision(await response.json() as RouterReply);
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

export default function cactusReflex(pi: ExtensionAPI) {
  let lastRoute: { selected: string[]; total: number; confidence?: number; mode: "filtered" | "fail-open" } | null = null;

  pi.on("before_agent_start", async event => {
    const tools = summarizeTools(pi);
    const allNames = tools.map(tool => tool.name);
    const summaries: ToolSummary[] = tools.map(tool => ({
      name: tool.name,
      source: tool.source,
      description: tool.description,
    }));

    const decision = await routePrompt(event.prompt, tools);
    const selected = selectActiveToolNames(summaries, decision, event.prompt);
    await pi.setActiveTools(selected);

    lastRoute = {
      selected,
      total: allNames.length,
      confidence: decision?.confidence,
      mode: selected.length < allNames.length ? "filtered" : "fail-open",
    };

    pi.logger.debug("cactus-reflex route", {
      mode: lastRoute.mode,
      confidence: lastRoute.confidence,
      selected: selected.length,
      total: allNames.length,
    });
  });

  pi.on("session_shutdown", async () => {
    const names = pi.getAllTools().map(tool => tool.name);
    await pi.setActiveTools(names);
  });

  pi.registerCommand("cactus-reflex", {
    description: "Show Cactus reflex-router status for this OMP session",
    handler: async (_args, ctx) => {
      const status = lastRoute
        ? `Cactus reflex: ${lastRoute.mode}; ${lastRoute.selected.length}/${lastRoute.total} tools active${lastRoute.confidence === undefined ? "" : `; confidence ${lastRoute.confidence.toFixed(4)}`}`
        : "Cactus reflex: loaded; no prompt routed yet";
      ctx.ui.notify(status, "info");
    },
  });
}
","mode":"rewrite"}}

