{"path":"/Remote Desktop Commander/link_6ac5be5cd98881918f28af8bca260fb8/write_file","args":{"deviceId":"8e436233-df9a-46a5-a6cc-38b3b5043a11","path":"/Users/rbhanson/.omp/agent/cactus-reflex/router.py","content":"#!/usr/bin/env python3
"""Crash-isolated, resident Cactus Needle selector for Oh My Pi.
Only routes tool names. Does not invoke or execute tools.
"""
from __future__ import annotations

import json
import os
import select
import statistics
import subprocess
import sys
import threading
import time
from collections import deque
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any

os.environ.setdefault("NEEDLE_TELEMETRY", "0")
os.environ.setdefault("DO_NOT_TRACK", "1")

HOST = "127.0.0.1"
PORT = int(os.environ.get("CACTUS_REFLEX_PORT", "8765"))
ROOT = Path(__file__).resolve().parent
LOGS = ROOT / "logs"
LOGS.mkdir(parents=True, exist_ok=True)

_lock = threading.RLock()
_worker: subprocess.Popen | None = None
_stderr = None
_latency_ms: deque[float] = deque(maxlen=200)
_metrics = {"requests": 0, "success": 0, "failures": 0, "worker_starts": 0}
WORKER_TIMEOUT = 3.1


def _shutdown_worker() -> None:
    global _worker, _stderr
    if _worker is not None:
        try:
            _worker.kill()
            _worker.wait(timeout=1)
        except Exception:
            pass
        try:
            _worker.stdin.close()
            _worker.stdout.close()
        except Exception:
            pass
        _worker = None
    if _stderr is not None:
        try:
            _stderr.close()
        except Exception:
            pass
        _stderr = None


def _start_worker() -> subprocess.Popen:
    global _worker, _stderr
    if _worker is not None and _worker.poll() is None:
        return _worker
    _shutdown_worker()
    _stderr = open(LOGS / "needle.stderr.log", "ab", buffering=0)
    _worker = subprocess.Popen(
        [sys.executable, "-u", str(ROOT / "needle_worker.py")],
        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=_stderr,
        bufsize=1, text=True, close_fds=True,
        env={**os.environ, "NEEDLE_TELEMETRY": "0", "DO_NOT_TRACK": "1"},
    )
    _metrics["worker_starts"] += 1
    return _worker


def _metrics_snapshot() -> dict[str, Any]:
    with _lock:
        data = dict(_metrics)
        data["worker_alive"] = _worker is not None and _worker.poll() is None
        data["worker_pid"] = _worker.pid if data["worker_alive"] else None
        data["latency_samples"] = len(_latency_ms)
        if _latency_ms:
            ordered = sorted(_latency_ms)
            data["latency_median_ms"] = round(statistics.median(ordered), 2)
            data["latency_p95_ms"] = round(ordered[min(len(ordered)-1, int(len(ordered)*0.95))], 2)
        return data


def route(prompt: str, tools: list[dict[str, Any]]) -> dict[str, Any]:
    with _lock:
        _metrics["requests"] += 1
        safe_tools = []
        for tool in tools[:3]:
            if not isinstance(tool, dict):
                continue
            name = tool.get("name")
            if not isinstance(name, str) or not name or len(name) > 96:
                continue
            safe_tools.append({
                "name": name,
                "description": str(tool.get("description", ""))[:240],
                "parameters": {"type": "object", "properties": {}},
            })
        if not isinstance(prompt, str) or not prompt.strip() or not safe_tools:
            return {"ok": True, "names": [], "confidence": 0.0}
        start = time.perf_counter()
        try:
            process = _start_worker()
            assert process.stdin is not None and process.stdout is not None
            process.stdin.write(json.dumps({"prompt": prompt[:6000], "tools": safe_tools})+"\n")
            process.stdin.flush()
            if not select.select([process.stdout], [], [], WORKER_TIMEOUT)[0]:
                raise TimeoutError("resident Needle worker timeout")
            line = process.stdout.readline()
            if not line:
                raise RuntimeError("resident Needle worker exited")
            reply = json.loads(line)
            if not isinstance(reply, dict) or reply.get("ok") is not True:
                raise RuntimeError(str(reply.get("error", "native worker returned invalid result")))
            valid = {tool["name"] for tool in safe_tools}
            reply["names"] = [name for name in reply.get("names", []) if name in valid]
            elapsed = (time.perf_counter()-start)*1000
            _latency_ms.append(elapsed)
            _metrics["success"] += 1
            reply["latency_ms"] = round(elapsed, 2)
            return reply
        except Exception as exc:
            _metrics["failures"] += 1
            _shutdown_worker()
            return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}


class Handler(BaseHTTPRequestHandler):
    server_version = "GMRI-CactusReflex/2.0"

    def log_message(self, fmt: str, *args: Any) -> None:
        pass

    def _json(self, code: int, payload: dict[str, Any]) -> None:
        body = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        try:
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def do_GET(self) -> None:
        if self.path == "/health":
            status = _metrics_snapshot()
            self._json(200, {"ok": True, "service": "cactus-reflex", "worker_alive": status["worker_alive"]})
        elif self.path == "/metrics":
            self._json(200, _metrics_snapshot())
        else:
            self._json(404, {"ok": False, "error": "not_found"})

    def do_POST(self) -> None:
        if self.path != "/route":
            return self._json(404, {"ok": False, "error": "not_found"})
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if length <= 0 or length > 65536:
                return self._json(413, {"ok": False, "error": "invalid body size"})
            data = json.loads(self.rfile.read(length))
            if not isinstance(data, dict) or not isinstance(data.get("prompt"), str) or not isinstance(data.get("tools"), list):
                return self._json(400, {"ok": False, "error": "invalid request"})
            self._json(200, route(data["prompt"], data["tools"]))
        except Exception as exc:
            self._json(500, {"ok": False, "error": f"{type(exc).__name__}: {exc}"})


class Server(ThreadingHTTPServer):
    daemon_threads = True


if __name__ == "__main__":
    with _lock:
        _start_worker()
    try:
        Server((HOST, PORT), Handler).serve_forever()
    finally:
        with _lock:
            _shutdown_worker()
","mode":"rewrite"}}

