 * Distinguish our previous temporary filtering from subsequent permission
 * changes made by the user or another extension.
 */
export function reconcileToolBaseline(
  baseline: readonly string[] | null,
  previouslySelected: readonly string[] | null,
  currentlyActive: readonly string[],
): string[] {
  if (!baseline || !previouslySelected) return [...currentlyActive];

  const current = new Set(currentlyActive);
  const previously = new Set(previouslySelected);
  const result = baseline.filter(name => !previously.has(name) || current.has(name));
  const known = new Set(result);
  for (const name of currentlyActive) {
    if (!previously.has(name) && !known.has(name)) {
      result.push(name);
      known.add(name);
    }
  }
  return result;
}

