}));

function session() {
  let current = mockTools.map(tool => tool.name);
  const events: Record<string, (event?:any) => Promise<void>> = {};
  cactusReflex({
    getAllTools: () => mockTools,
    getActiveTools: () => [...current],
    setActiveTools: async (names: string[]) => { current = [...names]; },
    on: (name: string, handler: (event?:any) => Promise<void>) => { events[name] = handler; },
    registerCommand: () => {},
    logger: {debug: () => {}},
  } as unknown as ExtensionAPI);
  return {
    route: (prompt: string) => events.before_agent_start({prompt}),
